**parseUser(data: unknown)**

`data` came from `JSON.parse`, so its type is `unknown`. Return a `User` (only its `name` and `age`) when `data` is an object with a string `name` and a number `age`; otherwise return `null`. The `as User` in the starter checks nothing.

```ts
type User = { name: string; age: number };

function parseUser(data: unknown): User | null {
  return data as User;
}
```

back:
// Why: A type annotation or `as` only tells the compiler what to assume. For data from
// outside, check it with typeof and `in`; TypeScript narrows `unknown` as you go.
// Docs: https://www.typescriptlang.org/docs/handbook/2/basic-types.html
type User = { name: string; age: number };

function parseUser(data: unknown): User | null {
  if (typeof data !== "object" || data === null) return null;
  if (!("name" in data) || typeof data.name !== "string") return null;
  if (!("age" in data) || typeof data.age !== "number") return null;
  return { name: data.name, age: data.age };
}

